/*
 * A137378  Triangle of the coefficient [x^k] of the polynomial 2^n*s_n(x)
 *          generated by exp(x*(1 - sqrt(1+t^2))/t) = Sum_{n>=0} s_n(x)*t^k/k!
 *          in row n, column k.
 * https://oeis.org/A137378
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  tabl, sign
 * Formula:   a(n) is the coefficient 2^r * s_r(x) in row r, column k where n
 *            = r*(r+1)/2 + k (0 ≤ k ≤ r). For r>0 and k>0 with (r+k) even,
 *            a_{r,k} = (r! * k * binomial(r-1, (r+k)/2 - 1)) / ( ((r+k)/2) *
 *            k! ) with sign (-1)^{(r+k)/2} ; all other entries equal 0. a(0)
 *            = 1
 * Range:     i8 n <= 11, i16 n <= 28, i32 n <= 65, i64 n <= 65, i128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* ----- integer square root (floor) for 64‑bit values ----- */
static idx_t int_sqrt_u64(idx_t x)
{
    idx_t lo = 0, hi = 0xffffffffULL, mid, sq, res = 0;
    while (lo <= hi) {
        mid = (lo + hi) >> 1;
        sq  = mid * mid;
        if (sq == x) return mid;
        if (sq < x) {
            res = mid;
            lo  = mid + 1;
        } else {
            hi  = mid - 1;
        }
    }
    return res;
}

/* ----- factorial table with lazy growth ----- */
static seq_t *FACT = NULL;
static idx_t FACT_SIZE = 0;

static void ensure_fact(idx_t n)
{
    if (FACT_SIZE > n) return;
    idx_t new_size = FACT_SIZE == 0 ? 1 : FACT_SIZE;
    while (new_size <= n) new_size <<= 1;
    seq_t *tmp = (seq_t *)realloc(FACT, new_size * sizeof(seq_t));
    if (!tmp) exit(EXIT_FAILURE);
    for (idx_t i = FACT_SIZE; i < new_size; ++i) {
        if (i == 0) tmp[i] = (seq_t)1;
        else        tmp[i] = tmp[i-1] * (seq_t)i;
    }
    FACT = tmp;
    FACT_SIZE = new_size;
}

static inline seq_t factorial(idx_t n)
{
    ensure_fact(n);
    return FACT[n];
}

/* ----- multiplicative binomial coefficient (exact) ----- */
static inline seq_t binomial(idx_t n, idx_t k)
{
    if (k > n) return (seq_t)0;
    if (k > n - k) k = n - k;
    seq_t res = (seq_t)1;
    for (idx_t i = 1; i <= k; ++i) {
        res = res * (seq_t)(n - k + i);
        res = res / (seq_t)i;
    }
    return res;
}

/* ----- main sequence function ----- */
seq_t a(idx_t N)
{
    /* Determine row r such that r*(r+1)/2 ≤ N < (r+1)*(r+2)/2 */
    idx_t r = 0;
    if (N != 0) {
        idx_t v = N * 8ULL + 1ULL;
        idx_t s = int_sqrt_u64(v);
        r = (s - 1ULL) >> 1;          /* floor((sqrt(8N+1)-1)/2) */
        while ((r + 1ULL) * (r + 2ULL) / 2ULL <= N) ++r;
        while (r * (r + 1ULL) / 2ULL > N) --r;
    }
    idx_t k = N - r * (r + 1ULL) / 2ULL;    /* column in row r */

    if (r == 0 && k == 0) return (seq_t)1;
    if (k == 0) return (seq_t)0;
    if (((r + k) & 1ULL) != 0ULL) return (seq_t)0;

    idx_t m = (r + k) >> 1;          /* m = (r+k)/2 */

    seq_t fact_r  = factorial(r);
    seq_t fact_k  = factorial(k);
    seq_t binom   = binomial(r - 1ULL, m - 1ULL);

    seq_t numerator   = fact_r * binom * (seq_t)k;
    seq_t denominator = (seq_t)m * fact_k;

    seq_t sign = ((m & 1ULL) == 0ULL) ? (seq_t)1 : (seq_t)(-1);

    return sign * (numerator / denominator);
}
